/* @lc app=leetcode id=3938 lang=kotlin */ class Solution { fun maxScore(grid: Array<IntArray>): Int = grid.size.let { m -> grid[0].size.let { n -> maxOf((grid.toList() + (0 until n).map { j -> IntArray(m) { grid[it][j] } }).maxOf { line -> (1 until line.size).fold(Int.MIN_VALUE / 2 to Int.MIN_VALUE / 2) { (f, best), i -> (line[i] + maxOf(line[i - 1], f)).let { it to maxOf(best, it) } }.second }, if (m > 2 && n > 2) (1 until m - 1).maxOf { i -> (1 until n - 1).maxOf { j -> grid[i][j] } } else Int.MIN_VALUE) } } }